package com.tekwatt.user.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="technicians")public class Technician{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=120)private String name;@Column(nullable=false,length=190)private String email;@Column(length=32)private String phone;@Column(length=500)private String skills;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected Technician(){}public Technician(UUID t,String n,String e,String p,String sk){id=UUID.randomUUID();tenantId=t;update(n,e,p,sk,"ACTIVE");createdAt=updatedAt;}public void update(String n,String e,String p,String sk,String s){name=n;email=e;phone=p;skills=sk;status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getName(){return name;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getSkills(){return skills;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
